package main

// Contracts: every contract lives in ext/contracts/<id path>/vN/ (mail.fallback/v1 → ext/contracts/mail/fallback/v1)
// with a README like an extension's. The tool reads every extension's Contracts() declaration (extkit.IDs(...) in its
// Implements, Defaults, Requires and WorksWith) and writes, into each contract's README and the catalogue in
// ext/contracts/README.md, which extensions provide it, require it and work with it.

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

const (
	contractsRoot  = "ext/contracts"
	catalogueFile  = "ext/contracts/README.md"
	indexStart     = "<!-- contracts:index (generated by `go run ./.github/extensions contracts` from each extension's Contracts(); don't edit) -->"
	indexEnd       = "<!-- /contracts:index -->"
	catalogueStart = "<!-- contracts:catalogue (generated by `go run ./.github/extensions contracts`; edit each contract's README front matter) -->"
	catalogueEnd   = "<!-- /contracts:catalogue -->"
)

// contractSections are the README sections every contract has, in this order.
var contractSections = []string{"Use", "Provide", "Extensions", "License"}

type contract struct {
	ID      string // mail.fallback/v1
	Dir     string // ext/contracts/mail/fallback/v1
	Owners  []string
	Summary string
}

// relation is how an extension declares a contract.
type relation int

const (
	provides relation = iota
	providesDefault
	requires
	worksWith
)

func (r relation) String() string {
	return [...]string{"provides", "provides (default)", "requires", "works with"}[r]
}

var versionDir = regexp.MustCompile(`^v[0-9]+$`)

// findContracts lists ext/contracts/<path>/vN folders (not internal/ or cmd/), sorted by id.
func findContracts() ([]contract, error) {
	var out []contract
	err := filepath.WalkDir(contractsRoot, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() {
			return nil
		}
		rel, _ := filepath.Rel(contractsRoot, p)
		rel = filepath.ToSlash(rel)
		if rel == "internal" || rel == "cmd" || strings.HasPrefix(d.Name(), ".") {
			return filepath.SkipDir
		}
		if !versionDir.MatchString(d.Name()) || rel == d.Name() {
			return nil
		}
		parts := strings.Split(rel, "/")
		c := contract{ID: strings.Join(parts[:len(parts)-1], ".") + "/" + d.Name(), Dir: filepath.ToSlash(p)}
		if src, err := os.ReadFile(p + "/README.md"); err == nil {
			c.Owners, c.Summary = frontMatter(string(src))
		}
		out = append(out, c)
		return filepath.SkipDir // a version's subpackages (remote/v1/remoteclient) aren't contracts
	})
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out, err
}

var frontRe = regexp.MustCompile(`(?s)\A---\n(.*?)\n---\n`)

// frontMatter reads `owners: ["@a", "@b"]` and `summary: ...` from a README's front matter.
func frontMatter(src string) (owners []string, summary string) {
	m := frontRe.FindStringSubmatch(src)
	if m == nil {
		return nil, ""
	}
	for _, line := range strings.Split(m[1], "\n") {
		k, v, ok := strings.Cut(line, ":")
		if !ok {
			continue
		}
		v = strings.TrimSpace(v)
		switch strings.TrimSpace(k) {
		case "owners":
			v = strings.Trim(v, "[]")
			for _, o := range strings.Split(v, ",") {
				if o = strings.Trim(strings.TrimSpace(o), `"'`); o != "" {
					owners = append(owners, o)
				}
			}
		case "summary":
			if u, err := strconv.Unquote(v); err == nil {
				v = u
			}
			summary = v
		}
	}
	return owners, summary
}

// declarations reads every extension's Contracts() method: contract id → extension name → relations.
func declarations() (map[string]map[string][]relation, error) {
	fields := map[string]relation{"Implements": provides, "Defaults": providesDefault, "Requires": requires, "WorksWith": worksWith}
	out := map[string]map[string][]relation{}
	add := func(id, ext string, r relation) {
		if out[id] == nil {
			out[id] = map[string][]relation{}
		}
		for _, have := range out[id][ext] {
			if have == r {
				return
			}
		}
		out[id][ext] = append(out[id][ext], r)
	}
	entries, err := os.ReadDir("ext")
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	for _, e := range entries {
		name := e.Name()
		if !e.IsDir() || name == "contracts" || name == "extkit" {
			continue
		}
		err := filepath.WalkDir("ext/"+name, func(p string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() {
				if b := d.Name(); b == "example" || b == "testdata" || strings.HasPrefix(b, ".") || b == "node_modules" {
					return filepath.SkipDir
				}
				return nil
			}
			if !strings.HasSuffix(p, ".go") || strings.HasSuffix(p, "_test.go") {
				return nil
			}
			f, err := parser.ParseFile(fset, p, nil, 0)
			if err != nil {
				return nil // not ours to judge; the build fails on it
			}
			for _, decl := range f.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Recv == nil || fn.Name.Name != "Contracts" || fn.Body == nil {
					continue
				}
				collect := func(field string, n ast.Node) {
					r, ok := fields[field]
					if !ok {
						return
					}
					ast.Inspect(n, func(n ast.Node) bool {
						if lit, ok := n.(*ast.BasicLit); ok && lit.Kind == token.STRING {
							if id, err := strconv.Unquote(lit.Value); err == nil {
								add(id, name, r)
							}
						}
						return true
					})
				}
				ast.Inspect(fn.Body, func(n ast.Node) bool {
					switch x := n.(type) {
					case *ast.KeyValueExpr:
						if k, ok := x.Key.(*ast.Ident); ok {
							collect(k.Name, x.Value)
						}
					case *ast.AssignStmt:
						for i, l := range x.Lhs {
							if sel, ok := l.(*ast.SelectorExpr); ok && i < len(x.Rhs) {
								collect(sel.Sel.Name, x.Rhs[i])
							}
						}
					}
					return true
				})
			}
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	// a default is also a provider: show it once, as the default
	for _, exts := range out {
		for ext, rs := range exts {
			var keep []relation
			isDefault := false
			for _, r := range rs {
				isDefault = isDefault || r == providesDefault
			}
			for _, r := range rs {
				if r == provides && isDefault {
					continue
				}
				keep = append(keep, r)
			}
			sort.Slice(keep, func(i, j int) bool { return keep[i] < keep[j] })
			exts[ext] = keep
		}
	}
	return out, nil
}

// extensionsOf lists the extensions with relation r (or providesDefault, for provides) to id, sorted.
func extensionsOf(decls map[string]map[string][]relation, id string, want ...relation) []string {
	var out []string
	for ext, rs := range decls[id] {
		for _, r := range rs {
			for _, w := range want {
				if r == w {
					label := ext
					if r == providesDefault {
						label += " (default)"
					}
					out = append(out, label)
				}
			}
		}
	}
	sort.Strings(out)
	return out
}

// contractIndex is the generated part of a contract README's ## Extensions section.
func contractIndex(c contract, decls map[string]map[string][]relation) string {
	var b strings.Builder
	b.WriteString(indexStart + "\n\n")
	type row struct {
		ext string
		r   relation
	}
	var rows []row
	for ext, rs := range decls[c.ID] {
		for _, r := range rs {
			rows = append(rows, row{ext, r})
		}
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].r != rows[j].r {
			return rows[i].r < rows[j].r
		}
		return rows[i].ext < rows[j].ext
	})
	if len(rows) == 0 {
		b.WriteString("No extension declares this contract yet.\n")
	} else {
		up := strings.Repeat("../", strings.Count(c.Dir, "/")+1) // back to the repo root
		b.WriteString("| Extension | |\n|---|---|\n")
		for _, r := range rows {
			fmt.Fprintf(&b, "| [%s](%sext/%s/README.md) | %s |\n", r.ext, up, r.ext, r.r)
		}
	}
	b.WriteString("\n" + indexEnd)
	return b.String()
}

// catalogue is the generated table in ext/contracts/README.md.
func catalogue(cs []contract, decls map[string]map[string][]relation) string {
	var b strings.Builder
	b.WriteString(catalogueStart + "\n\n| Contract | What it promises | Provided by | Required by | Works with | Owners |\n|---|---|---|---|---|---|\n")
	list := func(xs []string) string {
		if len(xs) == 0 {
			return ""
		}
		return strings.Join(xs, ", ")
	}
	for _, c := range cs {
		rel := strings.TrimPrefix(c.Dir, contractsRoot+"/")
		fmt.Fprintf(&b, "| [`%s`](%s/README.md) | %s | %s | %s | %s | %s |\n", c.ID, rel, strings.ReplaceAll(c.Summary, "|", `\|`),
			list(extensionsOf(decls, c.ID, providesDefault, provides)), list(extensionsOf(decls, c.ID, requires)),
			list(extensionsOf(decls, c.ID, worksWith)), strings.Join(c.Owners, ", "))
	}
	b.WriteString("\n" + catalogueEnd)
	return b.String()
}

// replaceBetween swaps the text from start through end (markers included) for repl.
func replaceBetween(src, start, end, repl string) (string, bool) {
	i := strings.Index(src, start)
	j := strings.Index(src, end)
	if i < 0 || j < i {
		return src, false
	}
	return src[:i] + repl + src[j+len(end):], true
}

// contractFiles returns every generated file's wanted content (repo path → content), and problems that stop it.
func contractFiles() (map[string]string, []string, error) {
	cs, err := findContracts()
	if err != nil {
		return nil, nil, err
	}
	decls, err := declarations()
	if err != nil {
		return nil, nil, err
	}
	want := map[string]string{}
	var problems []string
	for _, c := range cs {
		f := c.Dir + "/README.md"
		raw, err := os.ReadFile(f)
		if err != nil {
			problems = append(problems, f+": missing; every contract has a README (docs/extensions.md#contracts)")
			continue
		}
		out, ok := replaceBetween(string(raw), indexStart, indexEnd, contractIndex(c, decls))
		if !ok {
			problems = append(problems, f+": its ## Extensions section needs the markers "+indexStart+" … "+indexEnd)
			continue
		}
		want[f] = out
	}
	raw, err := os.ReadFile(catalogueFile)
	if err != nil {
		return nil, nil, err
	}
	out, ok := replaceBetween(string(raw), catalogueStart, catalogueEnd, catalogue(cs, decls))
	if !ok {
		problems = append(problems, catalogueFile+": needs the markers "+catalogueStart+" … "+catalogueEnd)
	} else {
		want[catalogueFile] = out
	}
	return want, problems, nil
}

// syncContracts writes the generated contract indexes and returns the files it changed.
func syncContracts() ([]string, error) {
	want, problems, err := contractFiles()
	if err != nil {
		return nil, err
	}
	if len(problems) > 0 {
		return nil, fmt.Errorf("%s", strings.Join(problems, "\n"))
	}
	var changed []string
	for f, content := range want {
		have, _ := os.ReadFile(f)
		if string(have) == content {
			continue
		}
		if err := os.WriteFile(f, []byte(content), 0o644); err != nil {
			return nil, err
		}
		changed = append(changed, f)
	}
	sort.Strings(changed)
	return changed, nil
}

var contractIDInCode = regexp.MustCompile(`(?:NewContract\[[^\]]*\]\(|//contract:id )"?([a-z0-9.]+/v[0-9]+)"?`)

// checkContracts: every contract has a README with owners, a summary and the sections in order; the generated indexes
// generate; the id in its code matches its folder; every id an extension declares is a contract.
func checkContracts() []string {
	cs, err := findContracts()
	if err != nil {
		return []string{err.Error()}
	}
	want, problems, err := contractFiles()
	if err != nil {
		return []string{err.Error()}
	}
	// A stale index isn't a problem: main regenerates it (.github/regenerate.sh), so a pull request never has to
	// commit a change to another owner's contract README.
	var stale []string
	for f, content := range want {
		if have, _ := os.ReadFile(f); string(have) != content {
			stale = append(stale, f)
		}
	}
	if len(stale) > 0 {
		sort.Strings(stale)
		fmt.Printf("note: %d generated contract indexes will change when main regenerates them (nothing to commit): %s\n", len(stale), strings.Join(stale, ", "))
	}
	known := map[string]bool{}
	for _, c := range cs {
		known[c.ID] = true
		f := c.Dir + "/README.md"
		raw, err := os.ReadFile(f)
		if err != nil {
			continue // reported above
		}
		src := string(raw)
		if len(c.Owners) == 0 {
			problems = append(problems, f+": front matter needs `owners: [\"@github-handle\"]` (whoever created the contract)")
		}
		if c.Summary == "" {
			problems = append(problems, f+": front matter needs `summary:` (one line: what the contract promises)")
		}
		var h2 []string
		fence := false
		for _, line := range strings.Split(src, "\n") {
			if strings.HasPrefix(strings.TrimSpace(line), "```") {
				fence = !fence
			}
			if !fence && strings.HasPrefix(line, "## ") {
				h2 = append(h2, strings.TrimSpace(line[3:]))
			}
		}
		next := 0
		for _, h := range h2 {
			if next < len(contractSections) && h == contractSections[next] {
				next++
			}
		}
		if next != len(contractSections) {
			problems = append(problems, fmt.Sprintf("%s: needs the sections ## %s, in that order (docs/extensions.md#contracts)", f, strings.Join(contractSections, ", ## ")))
		}
		if !licensedMIT(src, h2) {
			problems = append(problems, f+": must end with a `## License` section that says `MIT`")
		}
		// the id the code registers matches the folder
		files, _ := filepath.Glob(c.Dir + "/*.go")
		for _, gf := range files {
			if strings.HasSuffix(gf, "_test.go") {
				continue
			}
			code, err := os.ReadFile(gf)
			if err != nil {
				problems = append(problems, err.Error())
				continue
			}
			for _, m := range contractIDInCode.FindAllStringSubmatch(string(code), -1) {
				if m[1] != c.ID {
					problems = append(problems, fmt.Sprintf("%s: declares contract %q but lives in the folder for %q", gf, m[1], c.ID))
				}
			}
		}
	}
	decls, err := declarations()
	if err != nil {
		return append(problems, err.Error())
	}
	var ids []string
	for id := range decls {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	for _, id := range ids {
		if !known[id] {
			var exts []string
			for ext := range decls[id] {
				exts = append(exts, "ext/"+ext)
			}
			sort.Strings(exts)
			problems = append(problems, fmt.Sprintf("%s: declares contract %q, which has no folder in ext/contracts", strings.Join(exts, ", "), id))
		}
	}
	sort.Strings(problems)
	return problems
}
